22		"github.com/entireio/cli/cmd/entire/cli/termstyle"
23		"github.com/spf13/cobra"
24	)
25	
26	type summaryOptions struct {
27		Last             int
28		Agent            string
29		Branch           string
30		Me               bool
31		OutputJSON       bool
32		CheckpointPrefix string
33	}
34	
35	const (
36		defaultSummarySessionLimit = 10
37		maxSummaryRecentSessions   = 200
38	)
39	
40	type summarySessionView struct {
41		CheckpointID string               `json:"checkpoint_id"`
42		SessionID    string               `json:"session_id"`
43		Agent        string               `json:"agent"`
44		Model        string               `json:"model,omitempty"`
45		Branch       string               `json:"branch,omitempty"`
46		OwnerID      string               `json:"owner_id,omitempty"`
47		CreatedAt    string               `json:"created_at"`
48		Tokens       int                  `json:"tokens"`
49		Turns        int                  `json:"turns"`
50		HasSummary   bool                 `json:"has_summary"`
51		HasFacets    bool                 `json:"has_facets"`
52		Summary      summaryDetailView    `json:"summary"`
53		Facets       facets.SessionFacets `json:"facets"`
54	}
55	
56	type summaryDetailView struct {
57		Intent                  string                   `json:"intent,omitempty"`
58		Outcome                 string                   `json:"outcome,omitempty"`
59		Friction                []string                 `json:"friction,omitempty"`
60		Learnings               []insightsdb.LearningRow `json:"learnings,omitempty"`
61		ImplementationRationale []string                 `json:"implementation_rationale,omitempty"`
62		Tradeoffs               []string                 `json:"tradeoffs,omitempty"`
63		CodebasePatterns        []string                 `json:"codebase_patterns,omitempty"`
64	}
65	
66	var runSummaryTUI = summarytui.RunWithCurrentBranch //nolint:gochecknoglobals // injectable for testing
67	
68	// loadRepoSessions returns the most recent sessions whose checkpoints are reachable
69	// from the default branch. Returns nil silently on any error.
70	func loadRepoSessions(ctx context.Context) []insightsdb.SessionRow {
71		repoCheckpoints := buildRepoCheckpointSet(ctx)
72		if len(repoCheckpoints) == 0 {
73			return nil
74		}
75		worktreeRoot, err := paths.WorktreeRoot(ctx)
76		if err != nil {
77			return nil
78		}
79		idb, err := insightsdb.Open(filepath.Join(worktreeRoot, paths.EntireDir, "insights.db"))
80		if err != nil {
81			return nil
82		}
83		defer func() { _ = idb.Close() }()
84	
85		ids := make([]string, 0, len(repoCheckpoints))
86		for id := range repoCheckpoints {
87			ids = append(ids, id)
88		}
89		rows, err := idb.QueryByCheckpointIDs(ctx, ids, maxSummaryRecentSessions)
90		if err != nil {
91			return nil
92		}
93		return rows
94	}
95	
96	var summaryRefreshCacheIfStale = refreshCacheIfStale
97	
98	func newSummaryCmd() *cobra.Command {
99		opts := summaryOptions{Last: defaultSummarySessionLimit}
100	
101		cmd := &cobra.Command{
102			Use:   "summary [checkpoint-id]",
103			Short: "Browse source sessions with summaries and facets",
104			Args:  cobra.MaximumNArgs(1),
105			RunE: func(cmd *cobra.Command, args []string) error {
106				ctx := cmd.Context()
107				w := cmd.OutOrStdout()
108	
109				if checkDisabledGuard(ctx, w) {
110					return nil
111				}
112	
113				if !settings.IsSummarizeEnabled(ctx) {
114					fmt.Fprintln(w, "Summarization is required for summary browsing. Enable it in .entire/settings.json:")
115					fmt.Fprintln(w, `  { "strategy_options": { "summarize": { "enabled": true } } }`)
116					return nil
117				}
118	
119				if len(args) > 0 {
120					opts.CheckpointPrefix = args[0]
121				}
122	
123				return runSummary(ctx, w, opts)
124			},
125		}
126	
127		cmd.Flags().IntVar(&opts.Last, "last", opts.Last, "number of recent sessions to browse")
128		cmd.Flags().StringVar(&opts.Agent, "agent", "", "filter by agent name")
129		cmd.Flags().StringVar(&opts.Branch, "branch", "", "filter by branch")
130		cmd.Flags().BoolVar(&opts.Me, "me", false, "show only sessions for the active GitHub user")
131		cmd.Flags().BoolVar(&opts.OutputJSON, "json", false, "output sessions as JSON instead of launching the browser")
132		return cmd
133	}
134	
135	func runSummary(ctx context.Context, w io.Writer, opts summaryOptions) error {
136		rows, err := loadSummarySessions(ctx, opts)
137		if err != nil {
138			return err
139		}
140	
141		if opts.OutputJSON {
142			return renderSummaryJSON(w, rows)
143		}
144	
145		if IsAccessibleMode() {
146			renderSummaryText(w, rows)
147			return nil
148		}
149	
150		currentBranch := ""
151		if opts.CheckpointPrefix == "" {
152			if branch, err := GetCurrentBranch(ctx); err == nil {
153				currentBranch = branch
154			}
155		}
156	
157		// Load repo-scoped rows: the most recent sessions whose checkpoints
158		// are reachable from the default branch (independent view from current-branch rows).
159		repoRows := loadRepoSessions(ctx)
160	
161		return runSummaryTUI(ctx, rows, currentBranch, repoRows, generateForSession)
162	}
163	
164	func loadSummarySessions(ctx context.Context, opts summaryOptions) ([]insightsdb.SessionRow, error) {
165		worktreeRoot, err := paths.WorktreeRoot(ctx)
166		if err != nil {
167			return nil, fmt.Errorf("not in a git repository: %w", err)
168		}
169	
170		idb, err := insightsdb.Open(filepath.Join(worktreeRoot, paths.EntireDir, "insights.db"))
171		if err != nil {
172			return nil, fmt.Errorf("open insights cache: %w", err)
173		}
174		defer func() { _ = idb.Close() }()
175	
176		outputLimit := normalizedSummarySessionLimit(opts.Last)
177	
178		// Checkpoint prefix lookup: skip normal loading, query directly by prefix.
179		if opts.CheckpointPrefix != "" {
180			rows, err := idb.QueryByCheckpointPrefix(ctx, opts.CheckpointPrefix)
181			if err != nil {
182				return nil, fmt.Errorf("query by checkpoint: %w", err)
183			}
184			if len(rows) == 0 {
185				// Try refreshing cache in case the checkpoint hasn't been indexed yet.
186				if err := summaryRefreshCacheIfStale(ctx, idb); err != nil {
187					return nil, fmt.Errorf("refresh insights cache: %w", err)
188				}
189				rows, err = idb.QueryByCheckpointPrefix(ctx, opts.CheckpointPrefix)
190				if err != nil {
191					return nil, fmt.Errorf("query by checkpoint after refresh: %w", err)
192				}
193			}
194			if len(rows) == 0 {
195				return nil, fmt.Errorf("checkpoint not found: %s", opts.CheckpointPrefix)
196			}
197			return rows, nil
198		}
199	
200		rows, err := idb.QueryLastNSessions(ctx, maxSummaryRecentSessions)
201		if err != nil {
202			return nil, fmt.Errorf("query sessions: %w", err)
203		}
204		if len(rows) == 0 {
205			// First-run fallback: populate the cache if we have nothing local yet.
206			if err := summaryRefreshCacheIfStale(ctx, idb); err != nil {
207				return nil, fmt.Errorf("refresh insights cache: %w", err)
208			}
209			rows, err = idb.QueryLastNSessions(ctx, maxSummaryRecentSessions)
210			if err != nil {
211				return nil, fmt.Errorf("query sessions after refresh: %w", err)
212			}
213		}
214	
215		ownerID := ""
216		if opts.Me {
217			ownerID, err = githubidentity.ResolveUsername(ctx)
218			if err != nil {
219				return nil, fmt.Errorf("resolve github username: %w", err)
220			}
221		}
222	
223		hasCLIFilters := opts.Agent != "" || opts.Branch != "" || ownerID != ""
224	
225		filtered := make([]insightsdb.SessionRow, 0, len(rows))
226		for _, row := range rows {
227			if opts.Agent != "" && !strings.EqualFold(strings.TrimSpace(row.Agent), strings.TrimSpace(opts.Agent)) {
228				continue
229			}
230			if opts.Branch != "" && !strings.EqualFold(strings.TrimSpace(row.Branch), strings.TrimSpace(opts.Branch)) {
231				continue
232			}
233			if ownerID != "" && !strings.EqualFold(strings.TrimSpace(row.OwnerID), ownerID) {
234				continue
235			}
236			filtered = append(filtered, row)
237			// Only cap results when CLI filters or JSON output are in use.
238			// The TUI has its own branch filter, so it needs the full result set.
239			if hasCLIFilters && len(filtered) == outputLimit {
240				break
241			}
242		}
243	
244		return filtered, nil
245	}
246	
247	func normalizedSummarySessionLimit(last int) int {
248		if last <= 0 {
249			return defaultSummarySessionLimit
250		}
251		return min(last, maxSummaryRecentSessions)
252	}
253	
254	//nolint:musttag // nested external structs are part of the intended JSON payload
255	func renderSummaryJSON(w io.Writer, rows []insightsdb.SessionRow) error {
256		views := make([]summarySessionView, 0, len(rows))
257		for _, row := range rows {
258			views = append(views, summarySessionToView(row))
259		}
260	
261		enc := json.NewEncoder(w)
262		enc.SetIndent("", "  ")
263		if err := enc.Encode(views); err != nil {
264			return fmt.Errorf("encode summary sessions: %w", err)
265		}
266		return nil
267	}
