269	func renderSummaryText(w io.Writer, rows []insightsdb.SessionRow) {
270		s := termstyle.New(w)
271		fmt.Fprintln(w, s.Render(s.Bold, "Session Summary"))
272		if len(rows) == 0 {
273			fmt.Fprintln(w, "No sessions found.")
274			return
275		}
276	
277		for _, row := range rows {
278			fmt.Fprintf(w, "\n%s  %s  %s\n", row.CreatedAt.Format("2006-01-02 15:04"), row.Agent, row.SessionID)
279			if row.OwnerID != "" || row.OwnerName != "" || row.OwnerEmail != "" {
280				fmt.Fprintf(w, "Author: %s\n", fallbackText(row.OwnerID, "(unknown)"))
281				if row.OwnerName != "" {
282					fmt.Fprintf(w, "Author Name: %s\n", row.OwnerName)
283				}
284				if row.OwnerEmail != "" {
285					fmt.Fprintf(w, "Author Email: %s\n", row.OwnerEmail)
286				}
287			}
288			if row.Branch != "" {
289				fmt.Fprintf(w, "Branch: %s\n", row.Branch)
290			}
291			fmt.Fprintf(w, "Checkpoint: %s\n", row.CheckpointID)
292			fmt.Fprintf(w, "Summary: %s  Facets: %s\n", yesNo(row.HasSummary), yesNo(row.HasFacets))
293	
294			if row.HasSummary {
295				fmt.Fprintln(w, "Intent:")
296				fmt.Fprintf(w, "  %s\n", fallbackText(row.Intent, "No summary cached"))
297				fmt.Fprintln(w, "Outcome:")
298				fmt.Fprintf(w, "  %s\n", fallbackText(row.Outcome, "No summary cached"))
299				renderStringListSection(w, "Friction", row.Friction, "No friction recorded")
300				renderLearningSection(w, row.Learnings)
301				renderStringListSection(w, "Implementation Rationale", row.ImplementationRationale, "No implementation rationale recorded")
302				renderStringListSection(w, "Tradeoffs", row.Tradeoffs, "No tradeoffs recorded")
303				renderStringListSection(w, "Codebase Patterns", row.CodebasePatterns, "No codebase patterns recorded")
304			} else {
305				fmt.Fprintln(w, "No summary cached")
306			}
307	
308			renderFacetSections(w, row.Facets, row.HasFacets)
309		}
310	}
311	
312	func renderLearningSection(w io.Writer, learnings []insightsdb.LearningRow) {
313		if len(learnings) == 0 {
314			fmt.Fprintln(w, "Learnings:")
315			fmt.Fprintln(w, "  No learnings recorded")
316			return
317		}
318	
319		fmt.Fprintln(w, "Learnings:")
320		for _, learning := range learnings {
321			if learning.Path != "" {
322				fmt.Fprintf(w, "  - [%s] %s (%s)\n", learning.Scope, learning.Finding, learning.Path)
323				continue
324			}
325			fmt.Fprintf(w, "  - [%s] %s\n", learning.Scope, learning.Finding)
326		}
327	}
328	
329	func renderFacetSections(w io.Writer, data facets.SessionFacets, hasFacets bool) {
330		if !hasFacets {
331			fmt.Fprintln(w, "No facets cached")
332			return
333		}
334	
335		fmt.Fprintln(w, "Repeated Instructions:")
336		if len(data.RepeatedUserInstructions) == 0 {
337			fmt.Fprintln(w, "  None")
338		} else {
339			for _, item := range data.RepeatedUserInstructions {
340				fmt.Fprintf(w, "  - %s\n", item.Instruction)
341			}
342		}
343	
344		fmt.Fprintln(w, "Missing Context:")
345		if len(data.MissingContext) == 0 {
346			fmt.Fprintln(w, "  None")
347		} else {
348			for _, item := range data.MissingContext {
349				fmt.Fprintf(w, "  - %s\n", item.Item)
350			}
351		}
352	
353		fmt.Fprintln(w, "Review-Derived Rules:")
354		if len(data.ReviewDerivedRules) == 0 {
355			fmt.Fprintln(w, "  None")
356		} else {
357			for _, item := range data.ReviewDerivedRules {
358				fmt.Fprintf(w, "  - %s\n", item.Rule)
359			}
360		}
361	
362		fmt.Fprintln(w, "Failure Loops:")
363		if len(data.FailureLoops) == 0 {
364			fmt.Fprintln(w, "  None")
365		} else {
366			for _, item := range data.FailureLoops {
367				fmt.Fprintf(w, "  - %s (%d)\n", item.Description, item.Count)
368			}
369		}
370	
371		fmt.Fprintln(w, "Skill Signals:")
