399	func renderStringListSection(w io.Writer, title string, items []string, empty string) {
400		fmt.Fprintf(w, "%s:\n", title)
401		if len(items) == 0 {
402			fmt.Fprintf(w, "  %s\n", empty)
403			return
404		}
405		for _, item := range items {
406			fmt.Fprintf(w, "  - %s\n", item)
407		}
408	}
