1	package insightsdb
2	
3	import (
4		"context"
5		"database/sql"
6		"fmt"
7		"strings"
8		"time"
9	
10		"github.com/entireio/cli/cmd/entire/cli/facets"
11	)
12	
13	// SessionRow represents a single session for insertion into the cache.
14	// This is the denormalized view used by the CLI — callers populate it
15	// from checkpoint.CommittedMetadata.
16	type SessionRow struct {
17		CheckpointID string
18		SessionID    string
19		SessionIndex int
20		Agent        string
21		Model        string
22		Branch       string
23		OwnerName    string
24		OwnerID      string
25		OwnerEmail   string
26		CreatedAt    time.Time
27		InputTokens  int
28		CacheTokens  int
29		OutputTokens int
30		TotalTokens  int
31		APICallCount int
32		DurationMs   int64
33		TurnCount    int
34		Intent       string
35		Outcome      string
36		AgentPct     float64
37		// Score fields
38		OverallScore   float64
39		ScoreTokenEff  float64
40		ScoreFirstPass float64
41		ScoreFriction  float64
42		ScoreFocus     float64
43		HasSummary     bool
44		HasFacets      bool
45		// Denormalized arrays
46		FilesTouched            []string
47		Friction                []string
48		Learnings               []LearningRow
49		ImplementationRationale []string
50		Tradeoffs               []string
51		CodebasePatterns        []string
52		ToolCounts              map[string]int // tool name → invocation count
53		Facets                  facets.SessionFacets
54	}
55	
56	// LearningRow represents a single learning entry within a session.
57	type LearningRow struct {
58		Scope   string // "repo", "workflow", "code"
59		Finding string
60		Path    string // only meaningful when Scope is "code"
61	}
62	
63	// GetBranchTip returns the stored branch tip hash from cache_meta,
64	// or an empty string if it has not been set yet.
65	func (idb *InsightsDB) GetBranchTip(ctx context.Context) (string, error) {
66		var tip string
67		err := idb.db.QueryRowContext(ctx,
68			"SELECT value FROM cache_meta WHERE key = ?",
69			"branch_tip",
70		).Scan(&tip)
71		if err == sql.ErrNoRows {
72			return "", nil
73		}
74		if err != nil {
75			return "", fmt.Errorf("get branch tip: %w", err)
76		}
77		return tip, nil
78	}
79	
80	// SetBranchTip stores the branch tip hash in cache_meta.
81	// Overwrites any previously stored value.
82	func (idb *InsightsDB) SetBranchTip(ctx context.Context, tip string) error {
83		_, err := idb.db.ExecContext(ctx,
84			"INSERT OR REPLACE INTO cache_meta (key, value) VALUES (?, ?)",
85			"branch_tip",
86			tip,
87		)
88		if err != nil {
89			return fmt.Errorf("set branch tip: %w", err)
90		}
91		return nil
92	}
93	
94	// GetContentFingerprint returns a lightweight fingerprint of the insightsdb
95	// data state, based on row counts of key tables. This changes when facets
96	// are backfilled or new tool_calls are ingested, even if the branch tip
97	// hasn't changed.
98	func (idb *InsightsDB) GetContentFingerprint(ctx context.Context) (string, error) {
99		var fingerprint string
100		err := idb.db.QueryRowContext(ctx, `
101			SELECT
102				(SELECT COUNT(*) FROM sessions) || ':' ||
103				(SELECT COUNT(*) FROM skill_signals) || ':' ||
104				(SELECT COUNT(*) FROM review_rule_signals) || ':' ||
105				(SELECT COUNT(*) FROM tool_calls WHERE tool_name = 'Skill') || ':' ||
106				(SELECT COUNT(*) FROM sessions WHERE has_facets = 1)
107		`).Scan(&fingerprint)
108		if err != nil {
109			return "", fmt.Errorf("get content fingerprint: %w", err)
110		}
111		return fingerprint, nil
112	}
113	
114	// HasCheckpoint returns true if any session for the given checkpoint ID
115	// is already present in the sessions table.
116	func (idb *InsightsDB) HasCheckpoint(ctx context.Context, checkpointID string) (bool, error) {
117		var count int
