425			"failure_loops",
426			"skill_signals",
427			"review_rule_signals",
428		} {
429			if _, err = tx.ExecContext(ctx,
430				"DELETE FROM "+table+" WHERE checkpoint_id = ? AND session_index = ?", //nolint:gosec // table name is hardcoded
431				row.CheckpointID, row.SessionIndex,
432			); err != nil {
