443		}
444		return nil
445	}
446	
447	// nullableString converts an empty string to a SQL NULL value.
448	// Non-empty strings are passed through as-is.
449	func nullableString(s string) interface{} {
450		if s == "" {
451			return nil
452		}
453		return s
454	}
455	
456	func joinEvidence(values []string) interface{} {
457		if len(values) == 0 {
458			return nil
459		}
460		return strings.Join(values, "\n")
461	}
462	
463	func isEmptyFacets(v facets.SessionFacets) bool {
464		return len(v.RepeatedUserInstructions) == 0 &&
465			len(v.MissingContext) == 0 &&
466			len(v.FailureLoops) == 0 &&
467			len(v.SkillSignals) == 0 &&
468			len(v.ReviewDerivedRules) == 0 &&
469			len(v.RepoGotchas) == 0 &&
470			len(v.WorkflowGaps) == 0
471	}
