			"checkpoint_id", session.CheckpointID, "error", condErr)
	}
	if len(condensed) > 0 {
		input := summarize.Input{Transcript: condensed, FilesTouched: filesTouched}
		formatted := summarize.FormatCondensedTranscript(input)
		extractor := &facets.Extractor{Runner: &llmcli.Runner{}}
		facetResult, _, extractErr := extractor.Extract(ctx, formatted)
		if extractErr != nil {
			logging.Debug(ctx, "generateForSession: facet extraction failed",
				"checkpoint_id", session.CheckpointID, "error", extractErr)
		}
		if facetResult != nil {
			session.Facets = facetResult
		}
	}

	// Return partial success even if one phase failed.
	if genErr != nil {
		return session, fmt.Errorf("summary generation: %w", genErr)
	}
